/bin/zsh -lc "python3 - <<'PY'
import os,re,bisect
root='src'
# collect class inheritance simple names
texts={}
classes=[]
for dp,_,fs in os.walk(root):
  for fn in fs:
    if fn.endswith('.java'):
      path=os.path.join(dp,fn); txt=open(path).read(); texts[path]=txt
      # remove comments roughly for headers only
      clean=re.sub(r'/\\*.*?\\*/|//.*',' ',txt,flags=re.S)
      for m in re.finditer(r'\\bclass\\s+(\\w+)\\b(["'^'"\\{;]*)\\{', clean):
        ext=None
        em=re.search(r'\\bextends\\s+([\\w\\.]+)', m.group(2))
        if em: ext=em.group(1).split('.')[-1]
        classes.append((m.group(1),ext,path))
hier={'ForwardingObject'}
changed=True
while changed:
  changed=False
  for name,ext,path in classes:
    if ext in hier and name not in hier:
      hier.add(name); changed=True
# remove obvious parse glitch if any
hier={h for h in hier if h"'!='"'is'}

def mask_comments_strings(s):
  out=list(s); i=0; n=len(s)
  while i<n:
    if s.startswith('//',i):
      j=s.find('\\n',i); j=n if j<0 else j
      for k in range(i,j): out[k]=' '
      i=j
    elif s.startswith('/*',i):
      j=s.find('*/',i+2); j=n-2 if j<0 else j
      for k in range(i,j+2): out[k]=' '
      i=j+2
    elif s[i] in ('\"',\"'\"):
      q=s[i]; out[i]=' '; i+=1
      while i<n:
        if s[i]=='\\\\': out[i]=' '; i+=1; 
        if i<n: out[i]=' '
        if i<n and s[i]==q:
          i+=1; break
        i+=1
    else: i+=1
  return ''.join(out)

def line_starts(s):
  starts=[0]
  for m in re.finditer('\\n',s): starts.append(m.end())
  return starts

def line_no(starts,pos): return bisect.bisect_right(starts,pos)

def find_matching(clean,openpos):
  depth=0
  for i in range(openpos,len(clean)):
    c=clean[i]
    if c=='{': depth+=1
    elif c=='}':
      depth-=1
      if depth==0: return i
  return len(clean)

def scope_intervals(path,clean):
  intervals=[]
  # named class scopes
  for m in re.finditer(r'\\bclass\\s+(\\w+)\\b(["'^'"\\{;]*)\\{', clean):
    name=m.group(1); header=m.group(2); ext=None
    em=re.search(r'\\bextends\\s+([\\w\\.]+)', header)
    if em: ext=em.group(1).split('.')[-1]
    if name in hier or ext in hier:
      openpos=clean.find('{',m.start(),m.end())
      intervals.append((openpos,find_matching(clean,openpos),name))
  # anonymous new Forwarding*
  for m in re.finditer(r'new\\s+(\\w+)\\b["'^;{}]*'"\\{', clean):
    typ=m.group(1)
    if typ in hier:
      openpos=clean.find('{',m.start(),m.end())
      intervals.append((openpos,find_matching(clean,openpos),'anon'))
  return intervals

def in_intervals(intervals,pos):
  return any(a<=pos<=b for a,b,_ in intervals)

method_decl_re=re.compile(r'(?:(?:public|protected|private|static|final|abstract|synchronized|native|strictfp|default)\\s+)*(?:<["'^;{}()]+>'"\\s*)?[\\w@?\\[\\]<>.,\\s]+\\s+(\\w+)\\s*\\(["'^;{}]*'"\\)\\s*(?:throws\\s+[\\w\\s,<>.]+)?\\s*(?:\\{|;)')

def method_name_at(clean,pos):
  # if occurrence in method declaration itself
  line_start=clean.rfind('\\n',0,pos)+1; line_end=clean.find('\\n',pos); line_end=len(clean) if line_end<0 else line_end
  line=clean[line_start:line_end]
  mm=method_decl_re.search(line)
  if mm and ' delegate' in line: return mm.group(1)
  # scan backwards up to 5000 chars for last method header whose body contains pos
  start=max(0,pos-8000); region=clean[start:pos+1]
  candidates=[]
  for mm in method_decl_re.finditer(region):
    abs_start=start+mm.start(); abs_end=start+mm.end()
    if clean[abs_end-1]=='{':
      end=find_matching(clean,abs_end-1)
      if abs_end-1 <= pos <= end:
        candidates.append((abs_start,mm.group(1)))
  if candidates:
    return candidates[-1][1]
  return None

sites=[]; details=[]
for path,txt in texts.items():
  clean=mask_comments_strings(txt)
  intervals=scope_intervals(path,clean)
  if not intervals: continue
  starts=line_starts(txt)
  for m in re.finditer(r'\\bdelegate\\s*\\(', clean):
    if not in_intervals(intervals,m.start()): continue
    name=method_name_at(clean,m.start()) or '<unknown>'
    sites.append(f'{path}:{name}')
    details.append((path,line_no(starts,m.start()),name,txt[txt.rfind('\\n',0,m.start())+1:txt.find('\\n',m.start()) if txt.find('\\n',m.start())"'!=-1 else len(txt)].strip()))
for d in sorted(details):
  print('"'%s:%s:%s: %s'%d)
print('---SITES---')
for s in sorted(set(sites)):
  print(s)
print('count',len(set(sites)))
PY"

