/bin/zsh -lc "python3 - <<'PY'
import os,re,bisect,json
root='src'
texts={}
classes=[]
for dp,_,fs in os.walk(root):
 for fn in fs:
  if fn.endswith('.java'):
   p=os.path.join(dp,fn); s=open(p).read(); texts[p]=s

def mask(s):
 out=list(s); i=0; n=len(s)
 while i<n:
  if s.startswith('//',i):
   j=s.find('\\n',i); j=n if j<0 else j
   for k in range(i,j): out[k]=' '
   i=j
  elif s.startswith('/*',i):
   j=s.find('*/',i+2); j=n-2 if j<0 else j
   for k in range(i,j+2): out[k]=' '
   i=j+2
  elif s[i] in ('\"',\"'\"):
   q=s[i]; out[i]=' '; i+=1; esc=False
   while i<n:
    ch=s[i]; out[i]=' '
    if esc: esc=False
    elif ch=='\\\\': esc=True
    elif ch==q: i+=1; break
    i+=1
  else: i+=1
 return ''.join(out)
cleans={p:mask(s) for p,s in texts.items()}
# classes
for p,c in cleans.items():
 for m in re.finditer(r'\\bclass\\s+(\\w+)\\b(["'^'"\\{;]*)\\{', c):
  em=re.search(r'\\bextends\\s+([\\w\\.]+)',m.group(2)); ext=em.group(1).split('.')[-1] if em else None
  classes.append((m.group(1),ext,p))
hier={'ForwardingObject'}; ch=True
while ch:
 ch=False
 for name,ext,p in classes:
  if ext in hier and name not in hier:
   hier.add(name); ch=True
hier.discard('is')

def match(c,op):
 d=0
 for i in range(op,len(c)):
  if c[i]=='{': d+=1
  elif c[i]=='}':
   d-=1
   if d==0: return i
 return len(c)-1

def affected_scopes(c):
 scopes=[]
 for m in re.finditer(r'\\bclass\\s+(\\w+)\\b(["'^'"\\{;]*)\\{', c):
  name=m.group(1); em=re.search(r'\\bextends\\s+([\\w\\.]+)',m.group(2)); ext=em.group(1).split('.')[-1] if em else None
  if name in hier or ext in hier:
   op=c.find('{',m.start(),m.end()); scopes.append((op,match(c,op),name))
 for m in re.finditer(r'new\\s+(\\w+)\\b["'^;{}]*'"\\{', c):
  if m.group(1) in hier:
   op=c.find('{',m.start(),m.end()); scopes.append((op,match(c,op),'anon'))
 return scopes
control={'if','for','while','switch','catch','synchronized','try','else','do','return','new'}

def method_name_from_header(h):
 hs=' '.join(h.strip().split())
 if not hs or '=' in hs: return None
 # reject class/anon/array init
 if re.search(r'\\b(class|interface|enum)\\b',hs): return None
 pm=hs.rfind(')')
 if pm<0: return None
 lp=hs.rfind('(',0,pm)
 if lp<0: return None
 before=hs[:lp].strip()
 toks=re.findall(r'[A-Za-z_"'$]['"\\w"'$]*'"',before)
 if not toks: return None
 name=toks[-1]
 if name in control: return None
 # constructor possible; but no delegate calls in constructors likely
 return name

def method_intervals(c):
 intervals=[]
 for i,ch in enumerate(c):
  if ch=='{':
   j=max(c.rfind(';',0,i),c.rfind('{',0,i),c.rfind('}',0,i))
   h=c[j+1:i]
   name=method_name_from_header(h)
   if name:
    intervals.append((i,match(c,i),name))
 return intervals

def enclosing_method(methods,pos):
 cand=[(a,b,n) for a,b,n in methods if a<=pos<=b]
 if cand: return max(cand,key=lambda x:x[0])[2]
 # abstract/interface method declaration line
 return method_name_from_header(cleans_cur[cleans_cur.rfind('\\n',0,pos)+1: (cleans_cur.find('\\n',pos) if cleans_cur.find('\\n',pos)>=0 else len(cleans_cur))])

sites=set(); details=[]
for p,c in cleans.items():
 scopes=affected_scopes(c)
 if not scopes: continue
 methods=method_intervals(c)
 starts=[0]+[m.end() for m in re.finditer('\\n',c)]
 def inscope(pos): return any(a<=pos<=b for a,b,_ in scopes)
 cleans_cur=c
 for m in re.finditer(r'\\bdelegate\\s*\\(', c):
  if not inscope(m.start()): continue
  mn=enclosing_method(methods,m.start())
  if not mn: mn='<unknown>'
  sites.add(f'{p}:{mn}')
  line=bisect.bisect_right(starts,m.start())
  details.append((p,line,mn,texts[p][texts[p].rfind('\\n',0,m.start())+1:texts[p].find('\\n',m.start()) if texts[p].find('\\n',m.start())"'!=-1 else len(texts[p])].strip()))
for d in sorted(details): print('"'%s:%s:%s: %s'%d)
print('---SITES---')
for s in sorted(sites): print(s)
print('count',len(sites))
PY"

